// TH15 v1.00b st02bs.ecl.txt:507-573 BossCard1 (兎符「ストロベリーダンゴ」) + BossCard1_at 575-681.
// Source t0 = this enemy's first attack frame; target card frame = t0 + 120 opening buffer.
// Source timerReset at t=4, interrupt time=2400 -> attack deadline t=2404.
const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;
const SOURCE_LIMIT: int = 2404;

const TH15_PELLET2: int = 368;         // source type1
const TH15_INVERT_POPCORN: int = 384;  // source type2

// Source type0x200000 VELTIME: a=90, r=2.0, s=-999999 keeps the bullet direction.
// Each ring bullet decelerates along its own launch direction to 2.0 px/frame.
xformdef RING_VELTIME {
    step_speed(2fx, 90 + 65536 * EASE_LINEAR);
}

// Source type0x10 STEP: a=60, b=1, c=4 (fixed target angle), r=pi/2, s=1.0 or 1.5.
// One 60-frame segment: linear decay of the logical speed to 0 along the launch
// direction, then the direction becomes straight down and speed is restored to s.
xformdef SINGLE_STEP(final_speed: fx) {
    @60 step_speed(0fx, 60 + 65536 * EASE_LINEAR);
    set_angle(90deg);
    set_speed(final_speed);
}

// Source BossCard1_at. One async invocation per outer-loop pass (200 frames apart).
// Source float accumulators C (base angle rad), D (rad/step +0.776644) and E (dist +0.7).
// In BAM, one D step is 0.776644 rad = 8100.69; ring volley k uses C(2k)=8100.69*k*(2k-1),
// the single bullet uses C(2k+1)=8100.69*k*(2k+1); distances are E(2k)=1.4k and E(2k+1)/2.
async sub wave() {
    var rank: int = global(GVAR_RANK);
    var color: int = 2;
    var speed: fx = 2.5fx;
    var count: int = 4;
    var gap: int = 2;
    var iters: int = 45;
    if rank == 1 { speed = 3fx; gap = 1; iters = 90; }
    if rank == 2 { color = 4; speed = 3fx; gap = 1; iters = 90; count = 8; }
    if rank == 3 { color = 4; speed = 3fx; gap = 1; iters = 90; count = 10; }
    // ANIM a=1 retreats 4x the launch speed along each bullet's own angle; kept,
    // while the birth animation phase itself is omitted.
    var back: fx = 4fx * speed;
    var k: int = 0;
    while k < iters {
        if $frame >= self_int(1) { return; }
        var m_ring: int = k * (2*k - 1);
        var ring_base: int = 8100*m_ring + (69*m_ring)/100;
        var nd: fx = 1.4fx*(k as fx) - back;
        var bx: fx = $self_x;
        var by: fx = $self_y - 8fx;
        for i in 0..count {
            var a: angle = ((ring_base + (i*65536)/count) as angle);
            _ = fire(TH15_PELLET2, color, bx + nd*cos(a), by + nd*sin(a), speed, a, RING_VELTIME, none);
        }
        wait(gap);
        if $frame >= self_int(1) { return; }
        var m_one: int = k * (2*k + 1);
        var one_base: int = 8100*m_one + (69*m_one)/100;
        var nd1: fx = 0.7fx*(k as fx) + 0.35fx - back;
        var fs: fx = 1fx;
        if k % 2 != 0 { fs = 1.5fx; }
        var sa: angle = one_base as angle;
        _ = fire(TH15_INVERT_POPCORN, color, bx + nd1*cos(sa), by + nd1*sin(sa), speed, sa, SINGLE_STEP(fs), none);
        wait(gap);
        k = k + 1;
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    set_self_int(2, $frame);                 // source t0
    set_self_int(1, $frame+SOURCE_LIMIT);    // source interrupt deadline
    set_self_int(0, 60);                     // movement step index
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    // Source entry etCancel(640): rebuild the segment's own clear.
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    // Source t=0..94 has no emission; the t=4 movePosTime(60,4,(0,128)) is zero
    // displacement from the (0,128) entry position.
    card_wait(94);
    loop {
        if $frame >= self_int(1) { return; }
        spawn wave();
        card_wait(120);
        if $frame >= self_int(1) { return; }
        card_move_rand();
        card_wait(80);
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);   // source setHitbox(48,48)
    set_hurtbox(20fx);  // source setHurtbox(40,40)
    spell_begin(0, 10, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 2200, 0, 0, 0, boss_main);
    loop { wait(600); }
}

// TH15 BossCard1 moveRand(60,4,1.0) + moveLimit(0,128,240,64), same native algorithm as
// the verified modern-sample recipe: one fixed direction per call, speed 1-k/60, per-frame
// clamp x[-120,120] y[96,160] (inner selection zone x+-60, y112..144), no bounce.
// int0 = next source step, fx0/fx1 = logical unit direction. All source wait(n) inside
// this attack use card_wait(n) in the same owner task.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60-k) as fx / 60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source signed unit random * pi, kept as unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -60fx {
        a = r/3;
    } else if $self_x > 60fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Deliberately not normalized here, matching the source abs() order below.
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, epsilon 0.05 rad -> nearest BAM boundaries.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        if $frame >= self_int(1) { move_vel(0, 0deg, 0fx, EASE_LINEAR); return; }
        card_arm_next_step();
    }
}
